using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using LocalChat;
int passed=0;
void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS "+name);}
foreach(var good in new[]{"http://127.0.0.1:1234/v1","http://localhost:8000/v1/","http://[::1]:1234/v1"}) Check(LocalApi.Endpoint(good).IsLoopback,"allow "+good);
foreach(var bad in new[]{"https://example.com/v1","http://192.168.0.1/v1","file:///tmp/test","http://127.0.0.1.evil.com/v1","http://user:pass@localhost:1234/v1","http://localhost/v1?x=1","http://localhost/v1#x"}){
    bool rejected=false;try{LocalApi.Endpoint(bad);}catch(ArgumentException){rejected=true;}Check(rejected,"reject "+bad);
}
async Task TestServer(string body,string status,Func<Uri,Task> test,bool image=false,bool thinking=false,List<ChatMessage>? expectedMessages=null,JsonElement? expectedSchema=null){
    var tcp=new TcpListener(IPAddress.Loopback,0);tcp.Start();int port=((IPEndPoint)tcp.LocalEndpoint).Port;
    var server=Task.Run(async()=>{using var peer=await tcp.AcceptTcpClientAsync();using var stream=peer.GetStream();using var reader=new StreamReader(stream,Encoding.UTF8,leaveOpen:true);string header;int len=0;string first=(await reader.ReadLineAsync())!;while(!string.IsNullOrEmpty(header=(await reader.ReadLineAsync())!)){if(header.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))len=int.Parse(header.Split(':')[1]);}async Task<string> ReadChars(int amount){char[] chars=new char[amount];int got=0;while(got<amount){int n=await reader.ReadAsync(chars.AsMemory(got,amount-got));if(n==0)throw new Exception("short request");got+=n;}return new string(chars);}
        string json;
        if(len>0)json=await ReadChars(len);
        else{var bodyText=new StringBuilder();while(true){string size=(await reader.ReadLineAsync())!;int amount=Convert.ToInt32(size.Split(';')[0],16);if(amount==0){await reader.ReadLineAsync();break;}bodyText.Append(await ReadChars(amount));await reader.ReadLineAsync();}json=bodyText.ToString();}
        using var payload=JsonDocument.Parse(json);Check(payload.RootElement.GetProperty("chat_template_kwargs").GetProperty("enable_thinking").GetBoolean()==thinking,"explicit thinking mode payload");Check(payload.RootElement.GetProperty("model").GetString()=="qwen3","request model");if(expectedSchema.HasValue){var rf=payload.RootElement.GetProperty("response_format");Check(rf.GetProperty("type").GetString()=="json_schema","native structured-output type transported");Check(rf.GetProperty("json_schema").GetProperty("schema").GetRawText()==expectedSchema.Value.GetRawText(),"exact real provider schema transported");}else Check(!payload.RootElement.TryGetProperty("response_format",out _),"ordinary requests do not get a forced schema");Check(first.Contains("/v1/chat/completions"),"request route");var content=payload.RootElement.GetProperty("messages")[0].GetProperty("content");if(expectedMessages!=null){var wire=payload.RootElement.GetProperty("messages");Check(wire.GetArrayLength()==expectedMessages.Count,"all multi-turn messages transported");for(int i=0;i<expectedMessages.Count;i++)Check(wire[i].GetProperty("role").GetString()==expectedMessages[i].role&&wire[i].GetProperty("content").GetString()==expectedMessages[i].content,"exact chronological wire message "+i);}else if(image){Check(content.ValueKind==JsonValueKind.Array&&content[0].GetProperty("text").GetString()=="Привет"&&content[1].GetProperty("image_url").GetProperty("url").GetString()!.StartsWith("data:image/jpeg;base64,"),"vision payload local image");}else Check(content.GetString()=="Привет","request unicode");byte[] bytes=Encoding.UTF8.GetBytes(body);byte[] headers=Encoding.ASCII.GetBytes($"HTTP/1.1 {status}\r\nContent-Type: text/event-stream\r\nContent-Length: {bytes.Length}\r\nConnection: close\r\n\r\n");await stream.WriteAsync(headers);await stream.WriteAsync(bytes);});
    try{await test(new Uri($"http://127.0.0.1:{port}/v1/"));await server;}finally{tcp.Stop();}
}
var messages=new List<ChatMessage>{new("user","Привет")};
await TestServer("data: {\"choices\":[{\"delta\":{\"content\":\"Привет, \"}}]}\n\ndata: {\"choices\":[{\"delta\":{\"content\":\"Вась!\"}}]}\n\ndata: {\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n","200 OK",async uri=>{var chunks=new List<string>();var text=await LocalApi.ChatAsync(uri,"qwen3",messages,64,chunks.Add,CancellationToken.None);Check(text=="Привет, Вась!"&&chunks.Count==2,"stream Unicode chunks");});
await TestServer("data: {\"choices\":[{\"delta\":{\"content\":\"обрыв\"}}]}\n\n","200 OK",async uri=>{bool failed=false;try{await LocalApi.ChatAsync(uri,"qwen3",messages,64,_=>{},CancellationToken.None);}catch(Exception e){failed=e.Message.Contains("оборвал");}Check(failed,"reject incomplete response");});
await TestServer("model not loaded","400 Bad Request",async uri=>{bool failed=false;try{await LocalApi.ChatAsync(uri,"qwen3",messages,64,_=>{},CancellationToken.None);}catch(Exception e){failed=e.Message.Contains("HTTP 400");}Check(failed,"HTTP error is actionable");});
using(var cts=new CancellationTokenSource()){cts.Cancel();bool cancelled=false;try{await LocalApi.ChatAsync(new Uri("http://127.0.0.1:1/v1/"),"qwen3",messages,64,_=>{},cts.Token);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"cancel request");}
await TestServer("data: {\"choices\":[{\"delta\":{\"content\":\"Фото принято\"},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n","200 OK",async uri=>{string text=await LocalApi.ChatAsync(uri,"qwen3",messages,64,_=>{},CancellationToken.None,.6,new(){"data:image/jpeg;base64,TEST"});Check(text=="Фото принято","vision-compatible stream transport");},true);
await TestServer("data: {\"choices\":[{\"delta\":{\"reasoning_content\":\"private local processing\"}}]}\n\ndata: {\"choices\":[{\"delta\":{\"content\":\"done\"},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n","200 OK",async uri=>{string text=await LocalApi.ChatAsync(uri,"qwen3",messages,64,_=>{},CancellationToken.None,.2,thinking:true);Check(text=="done","thinking stream returns final answer without fabricating a work log");},thinking:true);
await TestServer("data: {\"choices\":[{\"delta\":{\"content\":\"partial code\"},\"finish_reason\":\"length\"}]}\n\ndata: [DONE]\n\n","200 OK",async uri=>{string finish="";var text=await LocalApi.ChatAsync(uri,"qwen3",messages,8192,_=>{},CancellationToken.None,onFinish:r=>finish=r);Check(finish=="length"&&text=="partial code","server length limit surfaced without changing generated text");});
var lastTurn=new List<ChatMessage>{new("system",ConversationInput.Priority),new("user","Создай сайт кафе на Cloudflare"),new("assistant","старый ответ"),new("user","Не сайт. Сколько будет 9+8?")};
await TestServer("data: {\"choices\":[{\"delta\":{\"content\":\"17\"},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n","200 OK",async uri=>{var text=await LocalApi.ChatAsync(uri,"qwen3",lastTurn,64,_=>{},CancellationToken.None);Check(text=="17","multi-turn transport returns current turn response");},expectedMessages:lastTurn);
var callSchema=JsonSerializer.SerializeToElement(new{type="object",properties=new{tool=new{type="string",@const="mcp_call"},arguments=new{type="object",properties=new{code=new{type="string"}},required=new[]{"code"}}},required=new[]{"tool","arguments"}});
await TestServer("data: {\"choices\":[{\"delta\":{\"content\":\"{}\"},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n","200 OK",async uri=>{await LocalApi.ChatAsync(uri,"qwen3",messages,512,_=>{},CancellationToken.None,responseSchema:callSchema);},expectedSchema:callSchema);
foreach(var finish in new[]{"content_filter","tool_calls","error"}){
 var eventBody="data: "+JsonSerializer.Serialize(new{choices=new[]{new{delta=new{content="partial"},finish_reason=finish}}})+"\n\ndata: [DONE]\n\n";
 await TestServer(eventBody,"200 OK",async uri=>{bool rejected=false;try{await LocalApi.ChatAsync(uri,"qwen3",messages,64,_=>{},CancellationToken.None);}catch(Exception e){rejected=e.Message.Contains("finish_reason="+finish);}Check(rejected,"non-success terminal response not marked complete: "+finish);});
}
await TestServer(new string('x',10000),"500 Server Error",async uri=>{try{await LocalApi.ChatAsync(uri,"qwen3",messages,64,_=>{},CancellationToken.None);Check(false,"HTTP error expected");}catch(Exception e){Check(e.Message.Length<1400&&e.Message.Contains("HTTP 500"),"HTTP diagnostic body is bounded");}});
Console.WriteLine($"{passed} checks passed");
